  async function saveAuctionDraft(){if(!supabase)return;if(!auctionProductId){setAuctionMessage('Create and select a draft product first.');return;}if(auctionTitle.trim().length<3||auctionTitle.trim().length>180||!Number.isFinite(Number(auctionStartingPrice))||Number(auctionStartingPrice)<0||!Number.isFinite(Number(auctionIncrement))||Number(auctionIncrement)<=0){setAuctionMessage('Check title, starting price and minimum increment.');return;}if(auctionStarts&&auctionEnds&&new Date(auctionEnds)<=new Date(auctionStarts)){setAuctionMessage('Auction end time must be after its start time.');return;}setAuctionBusy(true);setAuctionMessage('');const{error}=await supabase.rpc('admin_save_auction_draft',{p_auction_id:editingAuctionId||null,p_product_id:auctionProductId,p_title:auctionTitle,p_description:auctionDescription,p_image_url:auctionImage,p_category:auctionCategory,p_starting_price:Number(auctionStartingPrice),p_minimum_increment:Number(auctionIncrement),p_starts_at:auctionStarts?new Date(auctionStarts).toISOString():null,p_ends_at:auctionEnds?new Date(auctionEnds).toISOString():null});setAuctionBusy(false);if(error){setAuctionMessage(error.message);return;}const wasEditing=Boolean(editingAuctionId);setAuctionProductId('');setEditingAuctionId('');setAuctionTitle('');setAuctionDescription('');setAuctionImage('');setAuctionCategory('');setAuctionStartingPrice('0');setAuctionIncrement('1');setAuctionStarts('');setAuctionEnds('');setAuctionMessage(wasEditing?'Auction draft updated. It remains unpublished.':'Auction draft saved. It is not scheduled or live.');setRefresh(v=>v+1);}
 async function toggleFeature(key:string,enabled:boolean){
  if(!supabase||savingFeature!=='')return;
  if(enabled&&FINANCIAL_APPROVAL_LOCKED&&FINANCIAL_FEATURE_KEYS.has(key)){setFeatureMessage('This financial feature cannot be enabled until the owner approves the financial and compliance model.');return;}
  setSavingFeature(key);setFeatureMessage('');
  try{
   const {data,error}=await supabase.rpc('admin_set_feature_setting',{p_setting_key:key,p_enabled:enabled});
   if(error)throw error;
   if(data?.success!==true)throw new Error('The setting was not confirmed by the server.');
   setFeatureSettings(current=>({...current,[key]:enabled}));
   setFeatureMessage(`${featureLabels[key]??key} ${enabled?'enabled':'disabled'} and saved.`);
   setRefresh(v=>v+1);
  }catch(error){
   setFeatureMessage(error instanceof Error?error.message:'Could not save this feature setting. Please retry.');
  }finally{
   setSavingFeature('');
  }
 }
 async function createDuplicateId(){if(!supabase)return;const code=duplicateMainCode.trim(),under=duplicateUnderCode.trim();if(!code){setDuplicateMessage('Enter an active Main ID.');return;}if(!under){setDuplicateMessage('Select an active Under / Placement ID.');return;}setDuplicateBusy('create');setDuplicateMessage('');const{data,error}=await supabase.rpc('admin_create_duplicate_member_id',{p_main_member_code:code,p_under_member_code:under});setDuplicateBusy('');if(error){setDuplicateMessage(error.message);return;}setDuplicateMessage(`Created ${data.member_code} under ${data.under_member_code} for Main ID ${data.main_member_code} as Pending. Approve after reviewing the placement.`);setDuplicateMainCode('');setDuplicateUnderCode('');setRefresh(v=>v+1);}
 async function setDuplicateStatus(id:string,status:'active'|'suspended'|'closed'){if(!supabase)return;setDuplicateBusy(id);setDuplicateMessage('');const{error}=await supabase.rpc('admin_set_duplicate_id_status',{p_duplicate_id:id,p_status:status});setDuplicateBusy('');if(error){setDuplicateMessage(error.message);return;}setDuplicateMessage(`Duplicate ID status updated to ${status}.`);setRefresh(v=>v+1);}
