 async function reviewActivation(id:string,approve:boolean){
  if(approve && FINANCIAL_APPROVAL_LOCKED){setActivationMessage('Package approval and Bid Wallet credits are locked pending owner financial/legal approval and the reviewed Production database guard.');return;}
  if(!supabase)return;
  setReviewingActivation(id);setActivationMessage('');
  const {error}=await supabase.rpc('admin_review_package_activation',{p_activation_id:id,p_approve:approve});
  setReviewingActivation('');
  if(error){setActivationMessage(error.message);return;}
  setActivationMessage(approve?'Payment approved. Package activated and Bid Wallet credit posted.':'Payment rejected. No wallet credit was issued.');
  setRefresh(v=>v+1);
 }
 function downloadReport(filename:string,headers:string[],records:(string|number|null|undefined)[][]){const csv=csvDocument([headers,...records]);const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();URL.revokeObjectURL(url);}
 async function exportPagedReport<T>(label:string,filename:string,headers:string[],fetchPage:(offset:number)=>PromiseLike<any>,mapRows:(items:T[])=> (string|number|null|undefined)[][]){
 if(!supabase||reportExportBusy)return;setReportExportBusy(label);setReportExportMessage('');
 try{let all:T[]=[];for(let offset=0;;offset+=100){const {data,error}=await fetchPage(offset);if(error)throw error;const batch=(data??[]) as T[];all=all.concat(batch);if(batch.length<100)break;}if(!all.length){setReportExportMessage('No '+label+' records are available to export.');return;}const rows=mapRows(all);downloadReport(filename,headers,rows);setReportExportMessage('Exported '+rows.length+' '+label+' records.');}
 catch(e){setReportExportMessage(e instanceof Error?e.message:'Could not export '+label+'.');}finally{setReportExportBusy('');}
}
